package communication;import cern.accsoft.commons.util.value.Pair;import codec.lvtojava.LVDataDeserialiser;import codec.lvtojava.LVTypeDecoderImp;import jakarta.servlet.ServletInputStream;import jakarta.servlet.http.HttpServlet;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import types.labview.LVTypeDescriptor;import java.io.IOException;public class HTTPListener extends HttpServlet {        /**         * @param args         */        public static void main(String[] args) {        }        public void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {            ServletInputStream reader = request.getInputStream();            byte[] message = reader.readAllBytes();            LVTypeDecoderImp lvTypeDecoderImp = new LVTypeDecoderImp(message);            Pair<LVTypeDescriptor, Integer> typePair = lvTypeDecoderImp.decodeTypeDescriptor();            LVTypeDescriptor lvTypeDescriptor = typePair.getFirst();            LVDataDeserialiser lvDataDeserialiser = new LVDataDeserialiser(lvTypeDecoderImp.getBuffer());      System.out.println(lvDataDeserialiser.deserialise(lvTypeDescriptor).toString());        }}